export const PERMISSION_NAME_SET: ReadonlySet<string> = new Set(
  PERMISSION_CATALOG.map((p) => p.name),
);

export function isPermissionName(value: string): value is PermissionName {
  return PERMISSION_NAME_SET.has(value);
}

